#!/usr/bin/env python3
"""
Create the test_cases.xlsx template with comprehensive test cases.
Run this once to generate the template file.

Creates 50 test cases for each of the 5 agents (250 total):
- Router: direct_response vs database_research decisions
- Clarifier: proceed_with_research vs ask_clarification
- Planner: database selection across 16 databases
- DirectResponse: quality responses with golden references
- Summarizer: research synthesis with aggregated research
"""

import json
import os

from openpyxl import Workbook
