def create_template():
    """Create the Excel template with all sheets and comprehensive test data."""
    wb = Workbook()

    # Styles
    header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    header_font = Font(bold=True, color="FFFFFF")
    thin_border = Border(
        left=Side(style="thin"),
        right=Side(style="thin"),
        top=Side(style="thin"),
        bottom=Side(style="thin"),
    )

    sheets_data = [
        ("Router", ROUTER_CASES),
        ("Clarifier", CLARIFIER_CASES),
        ("Planner", PLANNER_CASES),
        ("DirectResponse", DIRECT_RESPONSE_CASES),
        ("Summarizer", SUMMARIZER_CASES),
    ]

    first_sheet = True
    for sheet_name, cases in sheets_data:
        if first_sheet:
            ws = wb.active
            ws.title = sheet_name
            first_sheet = False
        else:
            ws = wb.create_sheet(title=sheet_name)

        # Get agent-specific columns
        columns = AGENT_COLUMNS[sheet_name]

        # Write headers
        for col, header in enumerate(columns, 1):
            cell = ws.cell(row=1, column=col, value=header)
            cell.fill = header_fill
            cell.font = header_font
            cell.border = thin_border
            cell.alignment = Alignment(horizontal="center")

        # Write data rows
        for row_num, case in enumerate(cases, 2):
            for col, col_name in enumerate(columns, 1):
                value = case.get(col_name, "")
                cell = ws.cell(row=row_num, column=col, value=value)
                cell.border = thin_border
                if col_name in ["conversation", "aggregated_research", "golden_response"]:
                    cell.alignment = Alignment(wrap_text=True)

        # Auto-width columns (with max)
        for col in range(1, len(columns) + 1):
            col_letter = get_column_letter(col)
            max_width = 15
            for row in range(1, len(cases) + 2):
                cell_value = ws.cell(row=row, column=col).value
                if cell_value:
                    max_width = max(max_width, min(60, len(str(cell_value))))
            ws.column_dimensions[col_letter].width = max_width

    # Ensure output directory exists
    os.makedirs(os.path.dirname(OUTPUT_PATH), exist_ok=True)

    # Save
    wb.save(OUTPUT_PATH)
    print(f"Template created: {OUTPUT_PATH}")
    print(f"Sheets: {[s[0] for s in sheets_data]}")
    for sheet_name, cases in sheets_data:
        print(f"  {sheet_name}: {len(cases)} test cases")
    print(f"Total test cases: {sum(len(s[1]) for s in sheets_data)}")


if __name__ == "__main__":
    create_template()
